def facts():
    cases = {
        "const": Tensor.zeros(4, 32, dtype=dtypes.half, device="KTPU").contiguous(),
        "matmul": T(X) @ T(W).T,
        "vector": T(X) + T(Y),
    }
    out = {k: [L.plan(a).kind for a in asts(t)] for k, t in cases.items()}
    out["copy"] = [L.plan(a).kind for a in asts(T(X) * 1)]
    (p,) = [L.plan(a) for a in asts(Tensor.full((4, 32), 3, dtype=dtypes.half, device="KTPU").contiguous())]
    out["const_value"] = [np.unique(p.value).tolist(), str(p.value.dtype)]
    return out
